package solution

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"strings"
)

type FieldMatch struct{ Destination, Source string }
type fieldInfo struct{ name, typ string }

func findStruct(src, name string) (*ast.StructType, error) {
	f, err := parser.ParseFile(token.NewFileSet(), "input.go", src, 0)
	if err != nil { return nil, err }
	for _, d := range f.Decls {
		g, ok := d.(*ast.GenDecl); if !ok { continue }
		for _, s := range g.Specs {
			t, ok := s.(*ast.TypeSpec); if !ok || t.Name.Name != name { continue }
			st, ok := t.Type.(*ast.StructType); if !ok { return nil, fmt.Errorf("%s is not a struct", name) }
			return st, nil
		}
	}
	return nil, fmt.Errorf("struct %s not found", name)
}

func rendered(e ast.Expr) string { var b bytes.Buffer; _ = format.Node(&b, token.NewFileSet(), e); return b.String() }
func eligible(s string) bool { return len(s) > 0 && s[0] >= 'A' && s[0] <= 'Z' }

func InspectFieldMatches(dstSrc, dstName, srcSrc, srcName string) ([]FieldMatch, error) {
	dst, err := findStruct(dstSrc, dstName); if err != nil { return nil, err }
	src, err := findStruct(srcSrc, srcName); if err != nil { return nil, err }
	index := map[string][]fieldInfo{}
	for _, f := range src.Fields.List {
		for _, n := range f.Names { if eligible(n.Name) { k := strings.ToLower(n.Name); index[k] = append(index[k], fieldInfo{n.Name, rendered(f.Type)}) } }
	}
	out := make([]FieldMatch, 0)
	for _, f := range dst.Fields.List {
		for _, n := range f.Names {
			if !eligible(n.Name) { continue }
			c := index[strings.ToLower(n.Name)]
			if len(c) == 1 && c[0].typ == rendered(f.Type) { out = append(out, FieldMatch{n.Name, c[0].name}) }
		}
	}
	return out, nil
}
